  "content": "1|import * as React from 'react';
2|import {
3|  ListBox,
4|} from '@heroui/react';
5|import type { DesignerNode } from './types';
6|import { mergeClassNames, readString, resolveRuntimeNodeClassName, wrapDesignerChildSlot } from './runtimeShared';
7|import type { RuntimeRenderOptions } from './runtimeTypes';
8|import { resolveRuntimeComponentProps } from './runtimeNodeProps';
9|
10|type GenericComponent = React.ComponentType<Record<string, unknown>>;
11|
12|const GENERIC_LEAF_COMPONENTS: Record<string, GenericComponent> = {
13|  'heroui.listbox': ListBox as unknown as GenericComponent,
14|};
15|
16|const designInteractionClass = (mode: RuntimeRenderOptions['mode']): string | undefined =>
17|  mode === 'design' ? 'pointer-events-none' : undefined;
18|
19|export const renderHeroUiGenericLeafNode = (
20|  node: DesignerNode,
21|  paletteItemId: string,
22|  options: RuntimeRenderOptions,
23|): React.ReactNode | null => {
24|  const Component = GENERIC_LEAF_COMPONENTS[paletteItemId];
25|  const className = resolveRuntimeNodeClassName(node, designInteractionClass(options.mode));
26|  const passthrough = resolveRuntimeComponentProps(node, { libraryComponent: true });
27|
28|  if (Component) {
29|    return (
30|      <Component
31|        {...passthrough}
32|        className={className}
33|        style={options.style}
34|      >
35|        {readString(node.props.text) || readString(node.props.label) || undefined}
36|      </Component>
37|    );
38|  }
39|
40|  return (
41|    <div
42|      className={mergeClassNames(
43|        options.mode === 'runtime'
44|          ? 'inline-flex min-w-[96px] rounded-md border-2 border-dashed border-amber-300/90 bg-amber-50/60 px-2 py-1.5'
45|          : 'inline-flex min-w-[80px] rounded-md border border-dashed border-slate-300 px-2 py-1',
46|        className,
47|      )}
48|      style={options.style}
49|      title={readString(node.props.title)}
50|      aria-label={readString(node.props.ariaLabel)}
51|      data-designer-preview-placeholder={options.mode === 'runtime' ? 'true' : undefined}
52|    >
53|      {options.mode === 'runtime' ? (
54|        <div className="flex flex-col items-center gap-0.5 text-center">
55|          <span className="text-[10px] font-bold uppercase tracking-wider text-amber-600/90">Preview</span>
56|          <span className="text-[11px] font-semibold text-amber-900">
57|            {readString(node.props.text, readString(node.props.label, paletteItemId.replace(/^heroui\./, '')))}
58|          </span>
59|          <span className="text-[10px] text-amber-700/90">{paletteItemId}</span>
60|        </div>
61|      ) : (
62|        <span className="text-[11px] font-medium text-slate-700">
63|          {readString(node.props.text, readString(node.props.label, paletteItemId.replace(/^heroui\./, '')))}
64|        </span>
65|      )}
66|    </div>
67|  );
68|};
69|
70|export const renderHeroUiGenericStructuralNode = (
71|  node: DesignerNode,
72|  paletteItemId: string,
73|  options: RuntimeRenderOptions & { className?: string; children?: React.ReactNode },
74|): React.ReactNode => {
75|  const className = mergeClassNames(options.className, designInteractionClass(options.mode));
76|  const passthrough = resolveRuntimeComponentProps(node, { libraryComponent: true });
77|
78|  return (
79|    <div
80|      {...passthrough}
81|      className={className}
82|      style={options.style}
83|      title={readString(node.props.title)}
84|      aria-label={readString(node.props.ariaLabel)}
85|      data-designer-component={paletteItemId}
86|    >
87|      {wrapDesignerChildSlot(options.children, options.mode)}
88|    </div>
89|  );
90|};
91|"
